reused_helpers.definition:
int basic_spell(int player, int card, event_t event){
	//A spell that has no restriction such as targets, life to pay and so on, always returning 1 in EVENT_CAN_CAST and doing absolutely nothing in EVENT_CAST_SPELL
	return generic_spell(player, card, event, 0, NULL, NULL, 0, NULL);
}

int card_exploration(int player, int card, event_t event){
/* CARD_ID_EXPLORATION	3763
Exploration	|G
Enchantment
You may play an additional land on each of your turns. */

	// Used externally
	check_playable_lands(player);
	return global_enchantment(player, card, event);
}

int card_nantuko_shade(int player, int card, event_t event){
/* CARD_ID_NANTUKO_SHADE	1260
Nantuko Shade	|B|B
Creature - Insect Shade 2/1
|B: ~ gets +1/+1 until end of turn. */

	// Used externally
	return generic_shade_merge_pt(player, card, event, 0, MANACOST_B(1), 1,1);
}

int flash(int player, int card, event_t event){
	// Must also be set as type instant
	if (event == EVENT_CAN_CAST){
		return 1;
	} else if (event == EVENT_CAST_SPELL && affect_me(player, card)){
		ai_modifier -= 16;
	}
	return 0;
}

int generic_token(int player, int card, event_t event)
{
  int result;
  result = token_characteristic_setting_effects(player, card, event, player, card);
  return result;
}

int global_enchantment(int player, int card, event_t event){
	if( event == EVENT_SHOULD_AI_PLAY ){
		ai_modifier += (player == HUMAN) ? -8 : 8;
	}
	else if( event == EVENT_CAN_CAST ){
		return 1;
	}
	return 0;
}
